// ratelimit/limiter.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// New creates a Limiter. Returns an error on invalid parameters.
func New(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be > 0")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &Limiter{
		capacity: capacity,
		rate:     rate,
		tokens:   capacity,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens can be consumed at time now.
// It refills the bucket based on elapsed time since the last call.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}

	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}
