// ratelimit/limiter_test.go
package ratelimit

import (
	"testing"
	"time"
)

type fakeClock struct{ t time.Time }

func (c *fakeClock) Now() time.Time { return c.t }
func (c *fakeClock) Advance(d time.Duration) { c.t = c.t.Add(d) }

func TestNewValidation(t *testing.T) {
	fc := &fakeClock{t: time.Unix(0, 0)}
	tests := []struct {
		name     string
		cap, rat float64
		clock    Clock
		wantErr  bool
	}{
		{"ok", 10, 1, fc, false},
		{"zero capacity", 0, 1, fc, true},
		{"negative capacity", -1, 1, fc, true},
		{"zero rate", 10, 0, fc, true},
		{"negative rate", 10, -1, fc, true},
		{"nil clock", 10, 1, nil, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := New(tt.cap, tt.rat, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("err=%v wantErr=%v", err, tt.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	tests := []struct {
		name     string
		cap, rat float64
		steps    []struct {
			after time.Duration
			n     int
			want  bool
		}
	}{
		{
			name: "burst then reject",
			cap:  5, rat: 1,
			steps: []struct {
				after time.Duration
				n     int
				want  bool
			}{
				{0, 5, true},
				{0, 1, false},
			},
		},
		{
			name: "refill over time",
			cap:  5, rat: 1,
			steps: []struct {
				after time.Duration
				n     int
				want  bool
			}{
				{0, 5, true},
				{2 * time.Second, 2, true},
				{0, 1, false},
			},
		},
		{
			name: "cap prevents over-accumulation",
			cap:  3, rat: 1,
			steps: []struct {
				after time.Duration
				n     int
				want  bool
			}{
				{0, 3, true},
				{10 * time.Second, 3, true},
				{0, 1, false},
			},
		},
		{
			name: "partial consumption",
			cap:  10, rat: 2,
			steps: []struct {
				after time.Duration
				n     int
				want  bool
			}{
				{0, 4, true},
				{1 * time.Second, 4, true},
				{0, 3, true},
				{0, 1, false},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			fc := &fakeClock{t: base}
			l, err := New(tt.cap, tt.rat, fc)
			if err != nil {
				t.Fatal(err)
			}
			for i, s := range tt.steps {
				fc.Advance(s.after)
				got := l.AllowN(fc.Now(), s.n)
				if got != s.want {
					t.Errorf("step %d: AllowN(%v, %d)=%v want %v",
						i, s.after, s.n, got, s.want)
				}
			}
		})
	}
}

func TestConcurrent(t *testing.T) {
	fc := &fakeClock{t: base}
	l, _ := New(100, 10, fc)
	done := make(chan bool)
	for i := 0; i < 50; i++ {
		go func() {
			l.AllowN(fc.Now(), 1)
			done <- true
		}()
	}
	for i := 0; i < 50; i++ {
		<-done
	}
}
